import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:nsl_fyp/nsl/features.dart';

/// Stage-1 parity: does the Dart port of [Features.compute] agree with the
/// Python in section 4 of `lib/nsl_integration_spec.md`?
///
/// WEAKER than it looks, deliberately, because it was all that was available
/// while the real gate was blocked. The expected values were regenerated by
/// running the spec's own section 4 function over the landmark rows in
/// `assets/parity.json`, so this compares Dart against Python for the same
/// function definition: it catches porting mistakes (wrong loop order, dropped
/// epsilon, transposed index), not a section 4 that was itself mis-transcribed
/// from the training notebook.
///
/// What closes that gap is `integration_test/parity_test.dart` (section 6), run
/// against a fixture whose `landmarks`/`feats`/`logits` rows are aligned and
/// training-derived. Until it has passed on a device, treat [Features.compute]
/// as unverified against training.
void main() {
  late List<dynamic> rows;

  setUpAll(() {
    final f = File('test/fixtures/features_parity.json');
    rows = (jsonDecode(f.readAsStringSync()) as Map<String, dynamic>)['rows']
        as List<dynamic>;
  });

  test('Features.compute matches the section 4 Python '
      '(same definition, NOT training-derived -- see file header)', () {
    expect(rows, isNotEmpty);
    var worst = 0.0;
    var worstIdx = -1;
    var worstFeat = -1;

    for (var i = 0; i < rows.length; i++) {
      final row = rows[i] as Map<String, dynamic>;
      final raw = (row['landmarks'] as List)
          .map<List<double>>(
              (r) => (r as List).map((e) => (e as num).toDouble()).toList())
          .toList();
      final expected = (row['feats'] as List)
          .map((e) => (e as num).toDouble())
          .toList();

      final got = Features.compute(raw);
      expect(got, isNotNull, reason: 'compute() returned null at row $i');
      expect(got!.length, Features.dim);

      for (var j = 0; j < got.length; j++) {
        final d = (got[j] - expected[j]).abs();
        if (d > worst) {
          worst = d;
          worstIdx = i;
          worstFeat = j;
        }
      }
    }

    // The spec's own featDiff bound. Dart computes in 64-bit double where
    // NumPy used float32, so small non-zero diffs are expected.
    expect(
      worst,
      lessThan(1e-3),
      reason: 'worst featDiff=$worst at row $worstIdx feature $worstFeat. '
          'A large diff here is an ordering bug: check the i<j fingertip loop '
          'and the CURLS order (features 63-72 and 73-77).',
    );
  });

  test('compute rejects a wrong-sized landmark list', () {
    expect(Features.compute(const [[0, 0, 0]]), isNull);
  });

  test('compute rejects a degenerate (zero-scale) hand', () {
    // Every landmark at the wrist => scale is 0 => not classifiable.
    final degenerate = List.generate(21, (_) => <double>[1, 2, 3]);
    expect(Features.compute(degenerate), isNull);
  });

  test('standardise applies (f - mu) / sd elementwise', () {
    final f = Features.compute(
      (((rows.first as Map<String, dynamic>)['landmarks']) as List)
          .map<List<double>>(
              (r) => (r as List).map((e) => (e as num).toDouble()).toList())
          .toList(),
    )!;
    final mu = List<double>.filled(Features.dim, 0.5);
    final sd = List<double>.filled(Features.dim, 2.0);
    final std = Features.standardise(f, mu, sd);
    for (var i = 0; i < Features.dim; i++) {
      // Tolerance is float32 resolution, not float64: standardise() stores its
      // result in a Float32List, so the value is rounded on the way out.
      expect(std[i], closeTo((f[i] - 0.5) / 2.0, 1e-6));
    }
  });
}
